#include <string.h>
#include <stdint.h>
#include <time.h>
#include <stdlib.h>

#include "soc_address_map.h"
#include "printf.h"
#include "riscv_hw_if.h"
#include "soc_ifc.h"
#include "caliptra_ss_lc_ctrl_address_map.h"
#include "caliptra_ss_lib.h"
#include "fuse_ctrl.h"
#include "fuse_ctrl_mmap.h"
#include "lc_ctrl.h"

volatile char* stdout = (char *)SOC_MCI_TOP_MCI_REG_DEBUG_OUT;
#ifdef CPT_VERBOSITY
    enum printf_verbosity verbosity_g = CPT_VERBOSITY;
#else
    enum printf_verbosity verbosity_g = LOW;
#endif

int compare(uint32_t actual, uint32_t expected, uint32_t address) {
    if (actual != expected) {
        VPRINTF(LOW, "ERROR: @0x%08X: 0x%08X != 0x%08X\n",
                address, actual, expected);
        return 1;
    }
    return 0;
}
int part_read_compare(
        const partition_t* part,
        const uint32_t* exp_data,
        uint32_t exp_status,
        uint8_t include_digest
    ) {

    uint32_t act_data[2];
    int mismatches = 0;

    // Read and compare the data, for which the granularity and size
    // depend on the partition.
    for (uint32_t addr = part->address;
            addr < part->digest_address;
            addr += part->granularity / 8) {
        dai_rd(addr, &act_data[0], &act_data[1], part->granularity, exp_status);
        mismatches += compare(act_data[0], exp_data[0], addr);
        // Check second 32 bit only if the partition has a granularity
        // of more than 32 bit.
        if (part->granularity > 32) {
            mismatches += compare(act_data[1], exp_data[1], addr + 4);
        }
    }

    if (include_digest) {
        // Read and compare the digest, which always has a granularity and
        // size of 64 bit.
        dai_rd(part->digest_address, &act_data[0], &act_data[1], 64, exp_status);
        mismatches += compare(act_data[0], exp_data[0], part->digest_address);
        mismatches += compare(act_data[1], exp_data[1], part->digest_address + 4);
    }

    return mismatches;
}

// Use dai_zer to zeroize the given partition, expecting the DAI command to complete with status
// equal to exp_status.
//
// Return true if all zeroizations completed as expected.
bool part_zeroize(const partition_t* part, uint32_t exp_status) {
    // Firstly, zeroize the zeroization marker, which always has a
    // granularity and size of 64 bit.
    if (!dai_zer(part->zer_address, 64, exp_status, false)) return false;

    // Secondly, zeroize the data, for which the granularity and size
    // depend on the partition.
    for (uint32_t addr = part->address;
         addr < part->digest_address;
         addr += part->granularity / 8) {
        if (!dai_zer(addr, part->granularity, exp_status, false)) return false;
    }

    // Finally, zeroize the digest, which always has a granularity and
    // size of 64 bit.
    if (!dai_zer(part->digest_address, 64, exp_status, false)) return false;

    return true;
}

int check_part_zeroized(
        const partition_t* part,
        uint8_t only_data_and_digest,
        uint32_t exp_status) {
    uint32_t exp_ones[] = {0xFFFFFFFF, 0xFFFFFFFF};
    int mismatches = 0;

    // Read and compare the data and digest.
    mismatches += part_read_compare(part, exp_ones, 0, 1);

    if (only_data_and_digest) return mismatches;

    // Read the partition zeroization marker and check that the result
    // is all ones.
    uint32_t act_data[2];
    dai_rd(part->zer_address, &act_data[0], &act_data[1], 64, 0);
    mismatches += compare(act_data[0], exp_ones[0], part->zer_address) != 0;
    mismatches += compare(act_data[0], exp_ones[0], part->zer_address) != 0;

    return mismatches;
}

/**
 * This test emulates OTP corruption due to a SW bug (writing the same
 * data fuses twice with different values, which will corrupt ECC) and
 * checks that zeroization is still possible in this case.
 */
int test_sw_corruption (void) {
    // Initialize test constants.
    const uint32_t wr_data0[] = {0x11111111, 0x44444444};
    const uint32_t wr_data1[] = {0x33333333, 0xCCCCCCCC};
    const uint32_t exp_data[] = {
            wr_data0[0] | wr_data1[0],
            wr_data0[1] | wr_data1[1]
    };

    // Choose one of the zeroizable SW partitions.
    const partition_t part = partitions[CPTRA_SS_LOCK_HEK_PROD_0];

    // Step 1: Write the data fuses of the partition twice with
    // different values.

    // The first write sequence will go through without errors.
    for (uint32_t addr = part.address;
            addr < part.digest_address;
            addr += part.granularity / 8) {
        dai_wr(addr, wr_data0[0], wr_data0[1], part.granularity, 0);
    }
    // The second write sequence will trigger writeblank errors due to
    // ECC bits being toggled from 1 to 0. The writes *will* update the
    // words with an invalid ECC portion.
    for (uint32_t addr = part.address;
            addr < part.digest_address;
            addr += part.granularity / 8) {
        dai_wr(addr, wr_data1[0], wr_data1[1], part.granularity, OTP_CTRL_STATUS_DAI_ERROR_MASK);
    }

    // Step 2: Check that reading the data fuses now returns an
    // integrity error due to the second write in Step 1 corrupting
    // the ECC part of each word.
    if (part_read_compare(&part, exp_data, OTP_CTRL_STATUS_DAI_ERROR_MASK, 0) != 0) {
        VPRINTF(LOW, "ERROR: Step 2 failed!\n");
        return 1;
    }

    // Step 3: Reset.
    reset_fc_lcc_rtl();
    wait_dai_op_idle(0);

    // Step 4: Zeroize and check that zeroization succeeded.
    if (!part_zeroize(&part, 0)) {
        VPRINTF(LOW, "ERROR: Step 4 failed!\n");
        return 1;
    }

    // Step 5: Reset.
    reset_fc_lcc_rtl();
    wait_dai_op_idle(0);

    // Step 6: Read the partition back and ensure its now all ones.
    if (check_part_zeroized(&part, /*only_data_and_digest=*/0, 0) != 0) {
        VPRINTF(LOW, "ERROR: Step 6 failed!\n");
        return 1;
    }

    return 0;
}

/**
 * This test emulates OTP corruption due to a HW problem (fuse stuck at
 * 0) and checks that zeroization is still possible in this case (the
 * stuck-at fuse won't get "zeroized" to 1).
 */
int test_stuck_at_corruption (void) {
    int retval = 0;
    const partition_t part = partitions[CPTRA_SS_LOCK_HEK_PROD_1];

    // Step 1: Enable the fault.
    // Start by disabling FcZeroizeFuseAllOnes_A assertion, as it'll check that all
    // bits from the OTP memory will be set to "1"
    disable_fc_all_ones_sva();
    lsu_write_32(SOC_MCI_TOP_MCI_REG_DEBUG_OUT, CMD_FC_FORCE_FUSE_FAULT);

    // Step 2: Zeroize -- this should still succeed because the number
    // of bits stuck at 0 is lower than the threshold that would cause
    // zeroization to fail.
    if (!part_zeroize(&part, 0)) {
        VPRINTF(LOW, "ERROR: Step 2 failed!\n");
        retval = 1;
        goto epilogue;
    }

    // Step 3: Reset.
    reset_fc_lcc_rtl();
    wait_dai_op_idle(0);

    // Step 4: Check that data and digest have been completely zeroized.
    if (check_part_zeroized(&part, /*only_data_and_digest=*/1, 0) != 0) {
        VPRINTF(LOW, "ERROR: Step 4 failed!\n");
        retval = 1;
        goto epilogue;
    }

    // Step 5: Read the zeroization marker and check that it has been
    // zeroized except for the two bits stuck at 0.
    uint32_t act_data[2];
    dai_rd(part.zer_address, &act_data[0], &act_data[1], 64, 0);
    if (act_data[0] != 0xFFFFFFFC || act_data[1] != 0xFFFFFFFF) {
        VPRINTF(LOW, "ERROR: Step 5 failed (0x%08x 0x%08x)!\n",
                act_data[0], act_data[1]);
        retval = 1;
        goto epilogue;
    }

epilogue:
    // Disable the fault.
    lsu_write_32(SOC_MCI_TOP_MCI_REG_DEBUG_OUT, CMD_FC_RELEASE_FUSE_FAULT);
    // Re-enable FcZeroizeFuseAllOnes_A assertion
    enable_fc_all_ones_sva();
    return retval;
}

void main (void) {
    VPRINTF(LOW, "=================\nMCU Caliptra Boot Go\n=================\n\n");

    mcu_cptra_init_d();
    wait_dai_op_idle(0);

    lcc_initialization();
    grant_mcu_for_fc_writes();

    VPRINTF(LOW, "INFO: caliptra_ss_fuse_ctrl_zeroization_corrupt code.\n");

    if (test_sw_corruption() == 0) {
        VPRINTF(LOW, "test_sw_corruption PASSED\n");
    } else {
        VPRINTF(LOW, "test_sw_corruption FAILED\n");
    }

    if (test_stuck_at_corruption() == 0) {
        VPRINTF(LOW, "test_stuck_at_corruption PASSED\n");
    } else {
        VPRINTF(LOW, "test_stuck_at_corruption FAILED\n");
    }

    for (uint8_t ii = 0; ii < 160; ii++) {
        __asm__ volatile ("nop"); // Sleep loop as "nop"
    }

    SEND_STDOUT_CTRL(0xff);
}

