        }
    }



    VPRINTF(LOW, "INFO: Verifying SECRETX partition...\n");

    // Read back and verify SCRATCH item

    // Write to TEST_UNLOCK_TOKEN item
    if (granularity == 64){
        for (uint32_t i = 0; i < lenght_data; i++) {
            dai_rd(secret_base_addr+i*8, &read_data0, &read_data1, 64);
