    if (!part_zeroize(&part, /*only_marker=*/0, /*only_until_half_data=*/0, 0)) {
        VPRINTF(LOW, "ERROR: Step %d.11 failed!\n", test_idx);
        return false;
    }

    return end_test(&part);
}

